using System;using System.IO;using System.Linq;using System.Drawing;using System.Diagnostics;using System.Reflection;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
static class SeamlessInteractionTests {
 static T Field<T>(object o,string key){return (T)o.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Set(object o,string key,object value){o.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,value);}
 static void Call(object o,string key,params object[] args){o.GetType().GetMethod(key,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Pump(Func<bool> done){var until=DateTime.UtcNow.AddSeconds(6);while(!done()&&DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(10);}Check(done(),"background request finishes");}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();Program.TestMode=true;string root=args[0],output=args[1],python=args[2];
 string script=Path.Combine(root,"fake-service.py"),log=Path.Combine(root,"requests.txt");File.WriteAllText(script,"import sys,json,time\nfor line in sys.stdin:\n r=json.loads(line);c=r['command'];a=r['args']\n with open(sys.argv[1],'a') as f:f.write(c+' '+str(a)+'\\n')\n time.sleep(.2)\n result={'rows':[{'id':'stand','name':'Cached stand','members':['test']}]} if c=='stand_list' else {}\n print(json.dumps(dict(id=r['id'],ok=True,result=result)),flush=True)\n",new UTF8Encoding(false));
 using(var process=Process.Start(new ProcessStartInfo(python,"-u "+J.Quote(script)+" "+J.Quote(log)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true}))
 using(var main=new MainWindow(root,null,false,false)){
 main.StartPosition=FormStartPosition.Manual;main.Location=new Point(-2800,-1900);main.Show();var backend=new Backend(root);Set(backend,"process",process);Set(backend,"input",process.StandardInput);main.Backend=backend;
 Call(main,"Fill",J.O("mode","normal","rows",new object[]{J.O("name","test","data",J.O("label","Fixture","ram_mb",256,"cores",1))}));
 var gate=new ManualResetEventSlim(false);int calls=0,callback=0;Func<object> read=()=>{Interlocked.Increment(ref calls);gate.Wait();return "loaded";};var a=main.ReadAsync("same",read);var b=main.ReadAsync("same",read);Check(Object.ReferenceEquals(a,b),"identical pending reads share one task");
 main.Read("Загружаем…",read,result=>callback++,null,"same");main.Read("Загружаем…",read,result=>callback+=10,null,"same");Check(!main.Busy,"read does not lock the window");var tabs=Field<WorkspaceTabs>(main,"workspace");tabs.SelectedIndex=1;gate.Set();Pump(()=>callback==10);Check(calls==1&&tabs.SelectedIndex==1,"coalesced read applies latest callback without changing navigation");
 tabs.SelectedIndex=0;var mode=Field<LaunchModeSelector>(main,"launchMode");mode.PerformClick();Check(main.ModeSaving&&!main.Busy&&mode.Enabled,"mode saves in background with live toggle and navigation");mode.PerformClick();Check(mode.SelectedIndex==0,"latest requested mode is immediately visible");tabs.SelectedIndex=1;Pump(()=>!main.ModeSaving);Check(mode.SelectedIndex==0&&File.ReadAllLines(log).Count(x=>x.StartsWith("mode "))==2,"rapid mode changes settle to latest choice");
 Set(main,"standMode",true);Call(main,"LoadStands");Check(!main.Busy,"stand read does not block UI");Set(main,"standMode",false);tabs.SelectedIndex=1;Pump(()=>!Field<bool>(main,"standLoading"));Check(!Field<Panel>(main,"standDetail").Visible&&tabs.SelectedIndex==1,"late stand response cannot reopen a previous section");
 Set(main,"standMode",true);var stand=Field<System.Collections.Generic.List<object>>(main,"stands").Single();Set(main,"selectedStand",stand);Call(main,"ShowStand");var detail=Field<Panel>(main,"standDetail");var page=detail.Controls[0];Call(main,"ShowStand");Check(Object.ReferenceEquals(page,detail.Controls[0]),"unchanged stand preserves its existing controls");Set(main,"standMode",false);
 bool failure=false;main.Read("Проверка…",()=>{throw new IOException("fixture failure");},null,e=>failure=true,"failure");Pump(()=>failure);Check(!main.Busy&&main.TestError==null,"read failure is inline and releases navigation");main.Close();}
 using(var form=new Form{Size=new Size(200,100),BackColor=Color.White}){var button=new PolarButton{Size=new Size(160,40),Location=new Point(10,10),BackColor=Color.Black,ForeColor=Color.Black};form.Controls.Add(button);form.Show();Application.DoEvents();using(var image=new Bitmap(160,40)){button.DrawToBitmap(image,button.ClientRectangle);var colors=new System.Collections.Generic.HashSet<int>();for(int y=0;y<19;y++)for(int x=0;x<19;x++)colors.Add(image.GetPixel(x,y).ToArgb());Check(button.Region==null&&colors.Count>16,"curved edge retains intermediate anti-alias colors");image.Save(Path.Combine(output,"smooth-button.png"));}form.Close();}
 File.WriteAllText(Path.Combine(output,"seamless-results.txt"),"PASS: read coalescing, newest callback, responsive navigation, async mode round trip, stale stand response guard, inline failures, anti-alias edge colors");return 0;
 }catch(Exception e){File.WriteAllText(Path.Combine(args[1],"seamless-error.txt"),e.ToString());return 1;}}
}
